!function(){"use strict";jQuery(()=>{let t=null;document.getElementById("attach_src-button")?.addEventListener("click",e=>{if(e.preventDefault(),!wp)return;if(t)return void t.open();let{__:i}=wp.i18n;t=wp.media({button:{text:i("Use Lottie","am-lottieplayer")},library:{type:["application/zip","application/json"]},multiple:!1,title:i("Choose Lottie","am-lottieplayer")}),t?.on("select",()=>{let e=t?.state().get("selection").first().toJSON();document.querySelector('[name="src"]').value=e.url}),t?.open()})})}();
